mapper.select:
SELECT id, secret_hash, account_id, user_id, status, expires_at, revoked_at
FROM ai_mcp_access_key
WHERE id = #{accessKeyId}

mapper.update:
UPDATE ai_mcp_access_key
SET last_used_at = #{lastUsedAt}, update_time = #{lastUsedAt}
WHERE id = #{accessKeyId}
  AND status = 1
  AND revoked_at IS NULL
